      min-height: 100svh;
      display: grid;
      place-items: center;
      padding: clamp(28px, 6vw, 72px) 20px 120px;
    }

    .stack {
      width: min(100%, var(--max));
      text-align: center;
      display: flex;
      flex-direction: column;
      gap: clamp(14px, 2vw, 20px);
    }

    .brand {
      margin: 0 auto 10px;
      display: inline-flex;
      align-items: flex-end;
      justify-content: center;
      gap: 0.04em;
      color: var(--brand);
      user-select: none;
      letter-spacing: -0.03em;
      font-size: clamp(2rem, 8vw, 4.25rem);
      font-weight: 800;
      line-height: 1;
    }

    .brand .dash-e {
      display: inline-grid;
      place-items: center;
      width: 0.74em;
      height: 0.74em;
      border: 2.5px dashed currentColor;
      border-radius: 0.12em;
      transform: translateY(-0.05em);
      margin: 0 0.03em;
      font-size: 0.72em;
      opacity: 0.9;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.45rem, 3.2vw, 2rem);
      font-weight: 600;
      letter-spacing: -0.01em;
    }

    .sub {
      margin: 0;
      color: var(--muted);
      font-size: clamp(0.98rem, 2vw, 1.06rem);
    }

    .search-wrap {
      margin-top: 8px;
      position: relative;
      width: 100%;
    }

    .search-form {
      width: 100%;
      display: flex;
      align-items: center;
      position: relative;
    }

    .search-input {
      width: 100%;
      height: clamp(50px, 7vw, 56px);
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      background: #fff;
      color: var(--text);
      padding: 0 56px 0 16px;
      font-size: 1rem;
      transition: border-color .2s ease, box-shadow .2s ease;
    }

    .search-input::placeholder { color: #8b9097; }

    .search-input:focus {
      outline: none;
      border-color: var(--focus);
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--focus) 18%, #fff);
    }

    .search-btn {
      position: absolute;
      right: 8px;
      width: 40px;
      height: 40px;
      border-radius: 50%;
      border: none;
      background: transparent;
      color: #68707a;
      display: grid;
      place-items: center;
      cursor: pointer;
      transition: background-color .2s ease, color .2s ease;
