    .search-btn:hover,
    .search-btn:focus-visible {
      background: #eef1f4;
      color: #44515d;
      outline: none;
    }

    .search-icon {
      width: 19px;
      height: 19px;
      fill: none;
      stroke: currentColor;
      stroke-width: 2.1;
      stroke-linecap: round;
      stroke-linejoin: round;
    }

    .error-bar {
      margin-top: 10px;
      background: var(--bar);
      border-radius: var(--radius-sm);
      padding: 12px 14px;
      color: #68707a;
      font-size: 0.95rem;
      font-weight: 500;
      letter-spacing: 0.01em;
    }

    .rule {
      margin: 4px auto 0;
      width: 100%;
      border: 0;
      height: 1px;
      background: #e3e7ec;
    }

    .next {
      margin-top: 6px;
      text-align: left;
      display: inline-flex;
      flex-direction: column;
      align-self: center;
      min-width: min(100%, 300px);
      gap: 10px;
    }

    .next h2 {
      margin: 0 0 2px;
      font-size: 1.03rem;
      font-weight: 600;
      color: var(--text);
    }

    .next a {
      color: var(--link-muted);
      text-decoration-color: #a6adb5;
      text-underline-offset: 3px;
      font-size: 0.99rem;
    }

    .next a:hover,
    .next a:focus-visible {
      color: #4d5560;
      text-decoration-color: currentColor;
      outline: none;
    }

    .cookie {
      position: fixed;
      left: 0;
      right: 0;
      bottom: 0;
      background: #fcfcfd;
      border-top: 1px solid #e4e8ed;
      padding: 14px 16px;
      display: none;
      z-index: 30;
    }

    .cookie.show { display: block; }

    .cookie-inner {
      width: min(100%, 1080px);
      margin: 0 auto;
      display: flex;
      gap: 12px 18px;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
    }

    .cookie p {
      margin: 0;
      color: #555f69;
      font-size: 0.9rem;
      max-width: 880px;
    }

    .cookie a { color: #5b6671; }

    .cookie button {
      border: 1px solid #ccd3da;
      background: #fff;
      color: #29323b;
      border-radius: 999px;
      padding: 8px 14px;
      font-size: 0.9rem;
      cursor: pointer;
      transition: border-color .2s ease, background-color .2s ease;
    }

    .cookie button:hover,
    .cookie button:focus-visible {
      border-color: #9ea8b3;
      background: #f6f8fa;
      outline: none;
    }

    .modal {
      position: fixed;
      inset: 0;
      background: rgba(18, 18, 18, 0.46);
      display: none;
      place-items: center;
      padding: 20px;
      z-index: 40;
    }

    .modal.show { display: grid; }

    .panel {
      width: min(100%, 560px);
      background: #fff;
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 20px;
    }

    .panel h3 {
      margin: 0 0 10px;
      font-size: 1.14rem;
    }

    .panel p {
      margin: 0 0 14px;
      color: #5b6671;
      font-size: 0.95rem;
    }

    .pref {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 10px 0;
      border-top: 1px solid #eceff3;
      gap: 12px;
    }

    .pref:first-of-type { border-top: 0; }

    .pref label {
      font-size: 0.95rem;
      color: #2d3740;
    }

    .pref input[type="checkbox"] {
      width: 18px;
      height: 18px;
      accent-color: #41576d;
    }

    .panel-actions {
      margin-top: 16px;
      display: flex;
      justify-content: flex-end;
      gap: 10px;
    }

    .btn {
      border-radius: 8px;
      padding: 9px 14px;
      font-size: 0.92rem;
      border: 1px solid #c7ced6;
      background: #fff;
      cursor: pointer;
    }

    .btn.primary {
      border-color: #27313b;
      background: #27313b;
      color: #fff;
    }

    .btn:hover,
    .btn:focus-visible { outline: none; filter: brightness(0.97); }

    @media (max-width: 640px) {
      .page { padding-top: 30px; }
      .stack { gap: 12px; }
      .next { align-self: stretch; min-width: 0; }
      .cookie { padding-bottom: calc(12px + env(safe-area-inset-bottom)); }
    }
  </style>
</head>
<body>
  <main class="page" aria-labelledby="error-title">
    <section class="stack">
      <div class="brand" aria-label="IdeaForum logo">
        <span>Id</span><span class="dash-e" aria-hidden="true"></span><span>aForum</span>
      </div>

      <h1 id="error-title">Sorry, we can't find that.</h1>
      <p class="sub">Perhaps we can help you find the content you're looking for:</p>

      <div class="search-wrap">
        <form class="search-form" id="searchForm" role="search" aria-label="Search IdeaForum">
          <label for="searchInput" class="sr-only" style="position:absolute;left:-9999px;">Search IdeaForum</label>
          <input
            id="searchInput"
            class="search-input"
            name="q"
            type="search"
            autocomplete="off"
            placeholder="Search IdeaForum..."
            aria-label="Search IdeaForum"
            required
          />
          <button class="search-btn" type="submit" aria-label="Search">
            <svg class="search-icon" viewBox="0 0 24 24" aria-hidden="true">
              <circle cx="11" cy="11" r="7"></circle>
              <line x1="16.65" y1="16.65" x2="21" y2="21"></line>
            </svg>
          </button>
        </form>
      </div>

      <div class="error-bar" aria-live="polite">HTTP Error 404</div>
      <hr class="rule" />

      <nav class="next" aria-label="Next steps">
        <h2>What's next?</h2>
        <a href="./homepage.html">Go to the homepage</a>
        <a href="./help-desk.html">Visit our Help Desk</a>
      </nav>
    </section>
  </main>

  <aside class="cookie" id="cookieBanner" role="region" aria-label="Cookie consent">
    <div class="cookie-inner">
      <p>
        This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics,
        personalization, and targeted advertising. To learn more, view the following link:
        <a href="./privacy-policy.html" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
      </p>
      <button type="button" id="managePrefsBtn">Manage Preferences</button>
    </div>
  </aside>

  <div class="modal" id="prefsModal" role="dialog" aria-modal="true" aria-labelledby="prefsTitle">
    <div class="panel">
      <h3 id="prefsTitle">Cookie Preferences</h3>
      <p>Choose which optional cookies you'd like IdeaForum to use. Essential cookies remain enabled for site functionality.</p>

      <div class="pref">
        <label for="prefEssential">Essential cookies (required)</label>
        <input id="prefEssential" type="checkbox" checked disabled />
      </div>
      <div class="pref">
        <label for="prefAnalytics">Analytics cookies</label>
        <input id="prefAnalytics" type="checkbox" checked />
      </div>
      <div class="pref">
        <label for="prefPersonalization">Personalization cookies</label>
        <input id="prefPersonalization" type="checkbox" />
      </div>
      <div class="pref">
        <label for="prefAds">Targeted advertising cookies</label>
        <input id="prefAds" type="checkbox" />
      </div>

      <div class="panel-actions">
        <button class="btn" type="button" id="closePrefsBtn">Cancel</button>
        <button class="btn primary" type="button" id="savePrefsBtn">Save Preferences</button>
      </div>
    </div>
  </div>

  <script>
    (function () {
      const SEARCH_BASE = './search-results.html?q=';
      const COOKIE_KEY = 'ideaforum_cookie_consent_seen';
      const PREFS_KEY = 'ideaforum_cookie_preferences';

      const searchForm = document.getElementById('searchForm');
      const searchInput = document.getElementById('searchInput');
      const cookieBanner = document.getElementById('cookieBanner');
      const prefsModal = document.getElementById('prefsModal');
      const managePrefsBtn = document.getElementById('managePrefsBtn');
      const closePrefsBtn = document.getElementById('closePrefsBtn');
      const savePrefsBtn = document.getElementById('savePrefsBtn');

      const prefAnalytics = document.getElementById('prefAnalytics');
      const prefPersonalization = document.getElementById('prefPersonalization');
      const prefAds = document.getElementById('prefAds');

      if (!localStorage.getItem(COOKIE_KEY)) {
        cookieBanner.classList.add('show');
      }

      function openModal() {
        prefsModal.classList.add('show');
        const savedRaw = localStorage.getItem(PREFS_KEY);
        if (savedRaw) {
          try {
            const saved = JSON.parse(savedRaw);
            prefAnalytics.checked = Boolean(saved.analytics);
            prefPersonalization.checked = Boolean(saved.personalization);
            prefAds.checked = Boolean(saved.ads);
          } catch (_) {}
        }
      }

      function closeModal() {
        prefsModal.classList.remove('show');
      }

      managePrefsBtn.addEventListener('click', openModal);
      closePrefsBtn.addEventListener('click', closeModal);

      savePrefsBtn.addEventListener('click', function () {
        const payload = {
          analytics: prefAnalytics.checked,
          personalization: prefPersonalization.checked,
          ads: prefAds.checked,
          updatedAt: new Date().toISOString()
        };
        localStorage.setItem(PREFS_KEY, JSON.stringify(payload));
        localStorage.setItem(COOKIE_KEY, 'true');
        cookieBanner.classList.remove('show');
        closeModal();
      });

      prefsModal.addEventListener('click', function (event) {
        if (event.target === prefsModal) closeModal();
      });

      document.addEventListener('keydown', function (event) {
        if (event.key === 'Escape') closeModal();
      });

      searchForm.addEventListener('submit', function (event) {
        event.preventDefault();
        const query = searchInput.value.trim();
        if (!query) return;
        window.location.href = SEARCH_BASE + encodeURIComponent(query);
      });
    })();
  </script>
</body>
</html>
